	if authored {
		args = []string{"test", sourceRoot, "tests/authored.yaml", "--config", configPath, "--timeout", "20s", "--poll-interval", "25ms"}
	}
	code := executeScenarioInOwnedLifecycle(t, repoRootForTest(), args, endpoint, &stdout, &stderr)
	if code != 0 {
