		writeWorkflowValidationFixtureFile(t, filepath.Join(sourceRoot, "tests", "fixtures-scenario.yaml"), `
name: fixture materialization
seed: recorded
vars: {marker: "${'${1 + 1}'}"}
steps:
  - publish: fulfillment.requested
