		installScenarioPostgresRuntime(t)
		configPath = writeMockAgentRuntimeConfig(t, storebackend.BackendPostgres.String(), "")
		opts.StoreMode = storebackend.BackendPostgres.String()
		opts.StoreModeSet = true
	default:
		t.Fatalf("unsupported backend %q", backend)
	}
	opts.ConfigPath = configPath
	retainedRoot := t.TempDir()
	process := startOwnedMockLifecycleTestProcess(t, repoRootForTest(), retainedRoot, opts)
	process.waitForReadyLine()
	endpoint := "http://" + serveRuntimeAPIListenerFromOutput(t, process.outputString()) + "/v1/rpc"
	rt := servedTestProcessRuntime(t, process)
	if reader == nil || rt == nil || rt.Options.WorkflowModule == nil {
		t.Fatalf("%s derived scenario runtime is incomplete", backend)
	}
	plans, err := scenarioderivation.Compile(rt.Options.WorkflowModule.SemanticSource(), rt.EffectiveSourceIdentity, scenarioderivation.Request{FlowID: ".", Input: "fulfillment.requested"})
	if err != nil || len(plans) != 1 {
		t.Fatalf("%s compile negative selector plan: plans=%d err=%v", backend, len(plans), err)
	}
	selector, err := scenarioexecution.NewSelector(plans[0].Profile)
	if err != nil {
		t.Fatal(err)
	}
	selector.EffectiveSourceDigest = "sha256:" + strings.Repeat("0", 64)
	bundleHash, err := runtimecontracts.BundleHash(mustBundleFromSource(t, rt.Options.WorkflowModule.SemanticSource()))
	if err != nil {
		t.Fatal(err)
	}
	beforeMismatch := loadScenarioMutationCounts(t, reader, backend)
	rpcErr := requireServedJSONRPCError(t, endpoint, "event.publish", map[string]any{"bundle_hash": bundleHash, "event_name": "fulfillment.requested", "payload": map[string]any{"order_id": "must-not-publish"}, "idempotency_key": "derived-effective-source-mismatch-" + string(backend), "scenario_execution": map[string]any{"profile_id": selector.ProfileID, "profile_digest": selector.ProfileDigest, "effective_source_digest": selector.EffectiveSourceDigest}})
	if code, _ := rpcErr.Data["code"].(string); code != apiv1.BundleMismatchCode {
		t.Fatalf("%s mismatched effective source error = %#v", backend, rpcErr)
	}
	if afterPublish := loadScenarioMutationCounts(t, reader, backend); afterPublish != beforeMismatch {
		t.Fatalf("%s mismatched event.publish mutated state: before=%+v after=%+v", backend, beforeMismatch, afterPublish)
	}
	setupRunID := "00000000-0000-4000-8000-000000000201"
	setupEntityID := "00000000-0000-4000-8000-000000000202"
	rpcErr = requireServedJSONRPCError(t, endpoint, "test.setup_entities", map[string]any{"bundle_hash": bundleHash, "run_id": setupRunID, "idempotency_key": "derived-setup-effective-source-mismatch-" + string(backend), "entities": []any{map[string]any{"alias": "subject", "entity_id": setupEntityID, "flow_instance": "fulfillment", "entity_type": "subject", "current_state": "ready", "fields": map[string]any{}}}, "scenario_execution": map[string]any{"profile_id": selector.ProfileID, "profile_digest": selector.ProfileDigest, "effective_source_digest": selector.EffectiveSourceDigest}})
	if code, _ := rpcErr.Data["code"].(string); code != apiv1.BundleMismatchCode {
		t.Fatalf("%s mismatched setup effective source error = %#v", backend, rpcErr)
	}
	if afterSetup := loadScenarioMutationCounts(t, reader, backend); afterSetup != beforeMismatch {
		t.Fatalf("%s mismatched test.setup_entities mutated state: before=%+v after=%+v", backend, beforeMismatch, afterSetup)
	}
	var stdout, stderr bytes.Buffer
	started := time.Now()
	args := []string{"test", sourceRoot, "--derive", ".", "--input", "fulfillment.requested", "--config", configPath, "--timeout", "20s", "--poll-interval", "25ms"}
	if authored {
		args = []string{"test", sourceRoot, "tests/authored.yaml", "--config", configPath, "--timeout", "20s", "--poll-interval", "25ms"}
	}
	code := executeScenarioInOwnedLifecycle(t, repoRootForTest(), args, endpoint, &stdout, &stderr)
	if code != 0 {
		t.Fatalf("%s derived scenario code=%d stdout=%s stderr=%s", backend, code, stdout.String(), stderr.String())
	}
	if elapsed := time.Since(started); elapsed >= 60*time.Second {
		t.Fatalf("%s derived scenario took %s, want under 60s", backend, elapsed)
	}
	wantOutput := "scenario ok: derived:./fulfillment.requested"
	if authored {
		wantOutput = "scenario ok: tests/authored.yaml"
	}
	if !strings.Contains(stdout.String(), wantOutput) || strings.TrimSpace(stderr.String()) != "" {
		t.Fatalf("%s derived output stdout=%q stderr=%q", backend, stdout.String(), stderr.String())
	}
	requireExactScenarioExecutionProfile(t, reader, backend, rt.EffectiveSourceIdentity)
	beforeRestart := loadExactScenarioExecutionProfileRecord(t, reader, backend)
	if authored {
		if beforeRestart.profileID != "authored-stage-profile" {
			t.Fatalf("%s lost authored identity: %s", backend, beforeRestart.profileID)
		}
		profile, err := scenarioexecution.DecodeProfile(beforeRestart.raw, beforeRestart.profileDigest)
		if err != nil {
			t.Fatal(err)
		}
		responses := profile.ConnectorResponses()
		if len(responses) != 1 || responses[0].ToolID != "scenario.send" || string(responses[0].Response) != `{"marker":"${1 + 1}"}` {
			t.Fatalf("%s persisted witness=%#v, want exact materialized response", backend, responses)
		}
		var trace map[string]any
		requireServedJSONRPCResult(t, endpoint, "run.trace", map[string]any{"run_id": beforeRestart.runID}, &trace)
		rows, _ := trace["trace"].([]any)
		found := false
		responseFound := false
		for _, raw := range rows {
			row, _ := raw.(map[string]any)
			if row["event_name"] != "fulfillment.requested" && row["event_name"] != "fulfillment/send.succeeded" {
				continue
			}
			var public operatorread.OperatorEventFull
			requireServedJSONRPCResult(t, endpoint, "event.get", map[string]any{"event_id": row["event_id"]}, &public)
			payload := public.Payload
			if row["event_name"] == "fulfillment.requested" {
				if payload["order_id"] != "${1 + 1}" {
					t.Fatalf("%s publication rescanned materialized data: %#v", backend, payload)
				}
				found = true
			} else {
				result, _ := payload["result"].(map[string]any)
				if result["marker"] != "${1 + 1}" {
					t.Fatalf("%s dispatch lost authored witness: %#v", backend, payload)
				}
				responseFound = true
			}
		}
		if !found || !responseFound {
			t.Fatalf("%s authored payload/response absent from public trace: %#v", backend, trace)
		}
		closeServedScenarioFixtureRun(t, endpoint, bundleHash, beforeRestart.runID)
		stdout.Reset()
		stderr.Reset()
		if code := executeScenarioInOwnedLifecycle(t, repoRootForTest(), []string{"test", sourceRoot, "tests/fixtures-scenario.yaml", "--config", configPath, "--timeout", "20s", "--poll-interval", "25ms"}, endpoint, &stdout, &stderr); code != 0 {
			t.Fatalf("%s fixture command code=%d stdout=%s stderr=%s", backend, code, stdout.String(), stderr.String())
		}
		var listed struct {
			Runs []operatorread.RunHeader `json:"runs"`
		}
		requireServedJSONRPCResult(t, endpoint, "run.list", map[string]any{"bundle_hash": bundleHash}, &listed)
		fixtureRuns := 0
		for _, run := range listed.Runs {
			if run.RunID == beforeRestart.runID || run.Origin.EventType() != "fulfillment.requested" {
				continue
			}
			requireServedScenarioFixtureReadback(t, endpoint, run.RunID)
			closeServedScenarioFixtureRun(t, endpoint, bundleHash, run.RunID)
			fixtureRuns++
		}
		if fixtureRuns != 1 {
			t.Fatalf("%s fixture runs=%d, want one", backend, fixtureRuns)
		}
	}
	if _, err := os.Stat(credentialPath); !os.IsNotExist(err) {
		t.Fatalf("%s zero-credential journey created credential store %s: %v", backend, credentialPath, err)
	}
	if code := process.stop(); code != 0 {
		t.Fatalf("%s first derived runtime stop code = %d\n%s", backend, code, process.outputString())
	}
	previousReader := reader
	reader = nil
	restarted := startOwnedMockLifecycleTestProcess(t, repoRootForTest(), retainedRoot, opts)
	restarted.waitForReadyLine()
	if reader == nil || reader == previousReader {
		t.Fatalf("%s restart did not capture a fresh selected reader", backend)
	}
	restartedEndpoint := "http://" + serveRuntimeAPIListenerFromOutput(t, restarted.outputString()) + "/v1/rpc"
	restartedRuntime := servedTestProcessRuntime(t, restarted)
	if !restartedRuntime.EffectiveSourceIdentity.Equal(rt.EffectiveSourceIdentity) {
		t.Fatalf("%s restart effective identity changed: before=%s after=%s", backend, rt.EffectiveSourceIdentity.Digest(), restartedRuntime.EffectiveSourceIdentity.Digest())
	}
	afterRestart := loadExactScenarioExecutionProfileRecord(t, reader, backend)
	if beforeRestart.runID != afterRestart.runID || beforeRestart.profileID != afterRestart.profileID || beforeRestart.profileDigest != afterRestart.profileDigest || beforeRestart.effectiveDigest != afterRestart.effectiveDigest || !bytes.Equal(beforeRestart.raw, afterRestart.raw) {
		t.Fatalf("%s restart changed exact scenario execution profile", backend)
	}
	var resumed map[string]any
	requireServedJSONRPCResult(t, restartedEndpoint, "run.get", map[string]any{"run_id": beforeRestart.runID}, &resumed)
	run, _ := resumed["run"].(map[string]any)
	if run["run_id"] != beforeRestart.runID {
		t.Fatalf("%s restarted run readback = %#v, want original run", backend, resumed)
	}
	finalRecord := loadExactScenarioExecutionProfileRecord(t, reader, backend)
	if !bytes.Equal(beforeRestart.raw, finalRecord.raw) || beforeRestart.profileDigest != finalRecord.profileDigest || scenarioExecutionProfileCount(t, reader, backend) != 1 {
		t.Fatalf("%s restarted execution changed or duplicated durable scenario profile", backend)
	}
}

